const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const paradise = ee.Geometry.Point([-121.621, 39.775]); // Approximate center of Paradise, CA
  const roi = paradise.buffer(5000); // 5 km buffer around Paradise
  const startDate = '2018-11-07';
  const endDate = '2018-11-10';

  // 2. Data Acquisition & Check
  let fireCollection = ee.ImageCollection('MODIS/006/MCD14ML')
    .filterDate(startDate, endDate)
    .filterBounds(roi);

  const initialSize = await fireCollection.size().getInfo();
  if (initialSize === 0) {
    console.log(`No MODIS fire images found for ${startDate} to ${endDate} in the ROI.`);
    console.log('C1');
    return;
  }

  // Filter for high confidence fires (FireMask values 7, 8, 9)
  // According to MODIS documentation, 7 = nominal fire, 8 = high confidence fire, 9 = very high confidence fire
  // We'll consider any of these as an active fire.
  const activeFireCollection = fireCollection.map(image => {
    return image.select('FireMask').gte(7).selfMask().rename('active_fire');
  });

  // Check the size of the active fire collection after filtering (it should be the same as initialSize, just masked)
  // If no pixels meet the criteria, the sum will be 0.

  // Combine all fire masks into a single image to count total unique fire pixels over the period.
  // We'll mosaic the active fire images and sum the 'active_fire' band.
  // If any pixel was 'active_fire' on any day, it will have a value > 0.
  const combinedFireMask = activeFireCollection.sum().gt(0).rename('presence').selfMask();

  // 3. Processing
  // Calculate the number of active fire pixels within the ROI.
  // Using a small scale for pixel counting within the buffered area.
  const firePixelCount = await combinedFireMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000, // MODIS resolution is 1km, so 1000m scale is appropriate
    maxPixels: 1e9
  }).get('presence').getInfo();

  // 4. Validation & Final Answer
  if (firePixelCount === null) {
    console.log("Calculation failed to retrieve fire pixel count (result is null).");
    console.log("C3");
    return;
  }

  if (firePixelCount === 0) {
    console.log(`MODIS Images found: ${initialSize}`);
    console.log(`Active fire pixels detected: ${firePixelCount}`);
    console.log("No active fire pixels found after processing and masking.");
    console.log("B");
  } else {
    console.log(`MODIS Images found: ${initialSize}`);
    console.log(`Active fire pixels detected: ${firePixelCount}`);
    console.log("A");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
